let estado = flow.get("celda_ae2") || {
    fase: "reposo", avance: 50, inicioFase: null, duracionCNC: 0,
    piezasTerminadas: 0, alarma: false
};

if (msg.topic === "banda") {
    let luz = Number(msg.payload);
    if (estado.fase === "reposo" && Number.isFinite(luz) && luz < 40) {
        estado.fase = "enBanda";
        estado.inicioFase = Date.now();
    }
} else if (msg.topic === "avance") {
    let v = Number(msg.payload);
    if (Number.isFinite(v)) estado.avance = v;
} else if (msg.topic === "tick") {
    let ahora = Date.now();
    if (estado.fase === "enBanda" && ahora - estado.inicioFase >= 3000) {
        estado.fase = "enCNC";
        estado.inicioFase = ahora;
        estado.duracionCNC = 2000 + (estado.avance / 10) * 1000;
    } else if (estado.fase === "enCNC" && ahora - estado.inicioFase >= estado.duracionCNC) {
        estado.fase = "reposo";
        estado.piezasTerminadas++;
        estado.inicioFase = null;
    }
    estado.alarma = estado.fase === "enCNC" && (ahora - estado.inicioFase >= 12000);
}

flow.set("celda_ae2", estado);

return [
    { payload: estado.fase === "enBanda" ? 1 : 0 },
    { payload: estado.fase === "enCNC" ? 1 : 0 },
    { payload: `Fase: ${estado.fase} | Banda: ${estado.fase === "enBanda" ? "ON" : "OFF"} | CNC: ${estado.fase === "enCNC" ? "ON" : "OFF"} | Avance: ${estado.avance}% | Piezas: ${estado.piezasTerminadas} | Alarma: ${estado.alarma ? "ATASCO (>12s)" : "Normal"}` }
];
